// Drizzle table definitions used for type-safe queries.
// The SQL files in database/migrations/ are the source of truth; tests/db/schema.test.ts checks that these match them.
import { CATEGORY_TYPES } from "@thinktwice/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  date,
  integer,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

export const categoryTypeEnum = pgEnum("category_type", CATEGORY_TYPES);

/** A primary key generated by PostgreSQL as a UUIDv7. */
function primaryKey() {
  return uuid("id")
    .primaryKey()
    .default(sql`uuidv7()`);
}

/** created_at and updated_at columns (a database trigger keeps updated_at current). */
function timestamps() {
  return {
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  };
}

export const users = pgTable("users", {
  id: primaryKey(),
  firebaseUid: text("firebase_uid").notNull(),
  email: text("email").notNull(),
  timezone: text("timezone").notNull(),
  monthlyBudgetCents: integer("monthly_budget_cents"),
  ...timestamps(),
});

export const categories = pgTable("categories", {
  id: primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  type: categoryTypeEnum("type").notNull(),
  isHidden: boolean("is_hidden").notNull().default(false),
  sortOrder: integer("sort_order").notNull().default(0),
  ...timestamps(),
});

export const expenses = pgTable("expenses", {
  id: primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  categoryId: uuid("category_id").notNull(),
  amountCents: integer("amount_cents").notNull(),
  spentOn: date("spent_on", { mode: "string" }).notNull(),
  note: text("note"),
  ...timestamps(),
});
